import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for upper-triangular matrix multiplication
upper_tri_matmul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void upper_triu_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float val = 0.0f;
        if (col >= row) {
            for (int k = 0; k < N; ++k) {
                val += A[row * N + k] * B[k * N + col];
            }
        }
        C[row * N + col] = val;
    }
}

torch::Tensor upper_triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    upper_triu_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(),
                                             B.data_ptr<float>(),
                                             C.data_ptr<float>(),
                                             N);
    return C;
}
"""

upper_tri_matmul_cpp = "torch::Tensor upper_triu_matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code
upper_tri_matmul = load_inline(
    name="upper_tri_matmul",
    cpp_sources=upper_tri_matmul_cpp,
    cuda_sources=upper_tri_matmul_source,
    functions=["upper_triu_matmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.upper_triu_matmul = upper_tri_matmul

    def forward(self, A, B):
        return self.upper_triu_matmul.upper_triu_matmul_cuda(A, B)

N = 4096

def get_inputs():
    A = torch.triu(torch.randn(N, N))
    B = torch.triu(torch.randn(N, N))
    return [A.cuda(), B.cuda()]

def get_init_inputs():
    return []
